function validate([dict]) {
  if (!Array.isArray(dict) || dict.length < 1) return 'dict needs at least one string.';
  if (dict.some(w => typeof w !== 'string' || !/^[a-z]+$/.test(w))) return 'Each string is non-empty and uses only lowercase English letters.';
  const m = dict[0].length;
  if (dict.some(w => w.length !== m)) return 'All strings must have the same length.';
  if (dict.length * m > 100000) return 'dict may hold at most 10^5 characters in total.';
  if (new Set(dict).size !== dict.length) return 'The strings in dict must be distinct.';
  return null;
}

