function differByOne(dict) {
  const MOD = 1000000007;
  const BASE = 26;
  const m = dict[0].length;
  const hashes = [];
  for (const word of dict) {
    let hash = 0;
    for (let i = 0; i < m; i++) {
      hash = (hash * BASE + (word.charCodeAt(i) - 97)) % MOD;
    }
    hashes.push(hash);
  }

  const sameExcept = (a, b, skip) => {
    for (let i = 0; i < m; i++) {
      if (i !== skip && a[i] !== b[i]) {
        return false;
      }
    }
    return true;
  };

  let power = 1;
  for (let j = m - 1; j >= 0; j--) {
    const buckets = new Map();
    for (let w = 0; w < dict.length; w++) {
      const letter = dict[w].charCodeAt(j) - 97;
      const masked = (hashes[w] - ((letter * power) % MOD) + MOD) % MOD;
      const bucket = buckets.get(masked);
      if (bucket === undefined) {
        buckets.set(masked, [w]);
        continue;
      }
      for (const other of bucket) {
        if (sameExcept(dict[other], dict[w], j)) {
          return true;
        }
      }
      bucket.push(w);
    }
    power = (power * BASE) % MOD;
  }
  return false;
}

