function differByOne(dict) {
  // Compare every pair of strings character by character.
  for (let a = 0; a < dict.length; a++) {
    for (let b = a + 1; b < dict.length; b++) {
      let differences = 0;
      for (let i = 0; i < dict[a].length && differences < 2; i++) {
        if (dict[a][i] !== dict[b][i]) differences++;
      }
      if (differences === 1) return true;
    }
  }
  return false;
}

