function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const small = size === 'small';
  const m = small ? 1 + Math.floor(rand() * 4) : 8 + Math.floor(rand() * 13);
  const n = small ? 1 + Math.floor(rand() * 7) : Math.min(1999, Math.floor(20000 / m) - 1);
  const alphabet = small ? 2 + Math.floor(rand() * 3) : 26;
  // A coded word ends in the sum of its other letters (mod 26), so two coded words never differ in exactly one place.
  const codedWords = rand() < 0.5;
  const seen = new Set();
  const dict = [];
  for (let attempt = 0; dict.length < n && attempt < 20 * n; attempt++) {
    let word = '';
    let sum = 0;
    for (let i = 0; i < (codedWords ? m - 1 : m); i++) {
      const c = Math.floor(rand() * alphabet);
      sum += c;
      word += letters[c];
    }
    if (codedWords) word += letters[sum % 26];
    if (!seen.has(word)) {
      seen.add(word);
      dict.push(word);
    }
  }
  // Sometimes plant a word that differs from an existing one in a single position.
  if (codedWords && rand() < 0.5) {
    const base = dict[Math.floor(rand() * dict.length)];
    const p = Math.floor(rand() * m);
    const c = (base.charCodeAt(p) - 97 + 1 + Math.floor(rand() * 25)) % 26;
    const twin = base.slice(0, p) + letters[c] + base.slice(p + 1);
    if (!seen.has(twin)) dict.splice(Math.floor(rand() * (dict.length + 1)), 0, twin);
  }
  return [dict];
}
